  wire [7:0] product = sig4(am) * sig4(bm);
  wire [4:0] exp_sum = eff_exp(am) + eff_exp(bm);
  wire [6:0] out_mag = product_mag(exp_sum, product);
  assign out[7] = nan ? 1'b0 : sign;
  assign out[6:0] = nan ? 7'h7f : out_mag;
